create extension if not exists pgcrypto;create type "user_status" as enum ('ACTIVE','INVITED','SUSPENDED','INACTIVE');create type "role_code" as enum ('ADMIN','GESTOR','COORDENADOR','PROFESSOR','INTEGRANTE','COLABORADOR','JOGADOR_ASSOCIADO','VISUALIZADOR');create type "project_status" as enum ('PLANNING','ACTIVE','PAUSED','COMPLETED','ARCHIVED');create type "task_status" as enum ('TODO','IN_PROGRESS','BLOCKED','DONE','CANCELLED');create type "task_priority" as enum ('LOW','MEDIUM','HIGH','URGENT');create type "approval_status" as enum ('DRAFT','SUBMITTED','REVIEW','APPROVED','REJECTED','CHANGES_REQUESTED');create table "users"("id" uuid primary key default gen_random_uuid(),"name" varchar(160) not null,"email" varchar(320) not null unique,"password_hash" text,"primary_role" "role_code" not null default 'INTEGRANTE',"status" "user_status" not null default 'INVITED',"created_at" timestamptz not null default now());create table "roles"("id" uuid primary key default gen_random_uuid(),"code" "role_code" not null unique,"name" varchar(80) not null);create table "permissions"("id" uuid primary key default gen_random_uuid(),"code" varchar(120) not null unique,"name" varchar(120) not null);create table "user_roles"("user_id" uuid not null references "users"("id") on delete cascade,"role_id" uuid not null references "roles"("id") on delete cascade,"created_at" timestamptz not null default now(),primary key("user_id","role_id"));create table "projects"("id" uuid primary key default gen_random_uuid(),"name" varchar(180) not null,"slug" varchar(180) not null unique,"description" text,"status" "project_status" not null default 'PLANNING',"coordinator_id" uuid references "users"("id") on delete set null,"created_at" timestamptz not null default now());create index "projects_status_idx" on "projects"("status");create table "tasks"("id" uuid primary key default gen_random_uuid(),"title" varchar(220) not null,"description" text,"responsible_id" uuid references "users"("id") on delete set null,"project_id" uuid references "projects"("id") on delete set null,"due_at" timestamptz,"priority" "task_priority" not null default 'MEDIUM',"status" "task_status" not null default 'TODO',"created_at" timestamptz not null default now());create index "tasks_due_idx" on "tasks"("due_at");create table "notifications"("id" uuid primary key default gen_random_uuid(),"user_id" uuid not null references "users"("id") on delete cascade,"title" varchar(180) not null,"body" text not null,"read_at" timestamptz,"created_at" timestamptz not null default now());create table "audit_logs"("id" uuid primary key default gen_random_uuid(),"actor_id" uuid references "users"("id") on delete set null,"action" varchar(120) not null,"object_type" varchar(100) not null,"object_id" uuid,"created_at" timestamptz not null default now());create index "audit_logs_created_idx" on "audit_logs"("created_at");